// Models derived from the backend's OpenAPI contract (src/api/schema.d.ts, generated by `npm run gen:api`).
import type { components } from './schema';

type Schemas = components['schemas'];
/** springdoc marks every field optional; the API always sends them (nullable ones are typed explicitly below). */
type Model<K extends keyof Schemas> = Required<Schemas[K]>;

export type User = Model<'UserView'>;
export type TokenResponse = Model<'TokenResponse'> & { user: User };
export type Wallet = Model<'WalletResponse'>;
export type Transaction = Model<'TransactionView'>;
export type Bet = Model<'BetView'> & { settledAt: string | null };
export type Selection = Omit<Model<'SelectionView'>, 'odds' | 'result'> & { odds: number | null; result: string | null };
export type Market = Omit<Model<'MarketView'>, 'selections' | 'line' | 'suspendReason'> & {
  selections: Selection[];
  line: number | null;
  suspendReason: string | null;
};
export type SpinResult = Model<'SpinResult'> & { winningLines: Model<'LineView'>[] };
export type SlotState = Model<'StateView'>;
export type BonusPick = Model<'BonusPickResult'> & { revealedBoard: number[] | null };
export type PokerTableInfo = Model<'TableInfo'>;
export type SlotRound = Model<'RoundView'>;
export type Fairness = Model<'FairnessView'>;
export type ChatMessage = Model<'MessageView'>;
export type HandHistory = Model<'HandHistoryView'>;
export type SessionInfo = Model<'SessionRow'>;

export interface Page<T> {
  items: T[];
  nextCursor: string | null;
}

/** Normalized match state produced by the watcher. */
export interface MatchState {
  elapsed_s: number;
  net_worth: [number, number];
  objectives_alive: [number, number];
  objectives_mask: [number, number];
  spectators: number;
  winning_team: number | null;
}

export interface Team {
  name: string;
  side: 1 | 2;
  isWinner: boolean | null;
}

export interface Match {
  id: string;
  externalId: string;
  game: string;
  status: 'LIVE' | 'STALE' | 'ENDED' | 'REVIEW' | 'SETTLED' | 'VOID';
  startsAt: string;
  endedAt: string | null;
  state: Partial<MatchState>;
  teams: Team[];
  markets: Market[];
  chatRoomId: string | null;
  reviewReason: string | null;
}

export interface MatchEventView {
  id: number;
  type: string;
  data: Record<string, unknown>;
  occurredAt: string;
}

export interface OddsPoint {
  selectionId: string;
  odds: number;
  recordedAt: string;
}

export interface MatchDetail {
  match: Match;
  events: MatchEventView[];
  oddsHistory: OddsPoint[];
}

export interface AppConfig {
  currencyMode: 'PLAY_MONEY' | 'REAL_MONEY';
  tokenFiatRate: number;
  fiatCurrency: string;
  minStakeTokens: number;
  maxStakeTokens: number;
  licensedCountries: string[];
}

export type KycStatus = 'NONE' | 'PENDING' | 'VERIFIED' | 'REJECTED';

export interface KycCheck {
  check: string;
  outcome: 'PASS' | 'REVIEW' | 'FAIL';
  message: string;
}

export interface KycSubmission {
  id: string;
  userId: string;
  username: string;
  firstName: string;
  lastName: string;
  dateOfBirth: string;
  documentType: 'PASSPORT' | 'ID_CARD' | 'DRIVING_LICENCE';
  documentCountry: string;
  documentNumberLast4: string;
  documentExpiry: string;
  status: 'PENDING' | 'APPROVED' | 'REJECTED';
  decidedBy?: 'AUTO' | 'ADMIN';
  checks: KycCheck[];
  reason?: string;
  createdAt: string;
  decidedAt?: string;
}

export interface KycInfo {
  status: KycStatus;
  canWithdraw: boolean;
  /** Absent once verified (no cap). */
  depositCapTokens?: number;
  depositedTokens?: number;
  latest?: KycSubmission;
}

export interface Limit {
  limitType: 'deposit' | 'loss' | 'wager';
  period: 'daily' | 'weekly' | 'monthly';
  amountTokens: number | null;
  usedTokens: number;
  pendingAmountTokens?: number;
  pendingFrom?: string;
}

export interface SlotGame {
  id: string;
  name: string;
  rows: number;
  columns: number;
  paylines: number[][];
  symbols: Record<string, { name: string; type: string; pays: Record<string, number> }>;
  reels: string[][];
  scatterPays: Record<string, number>;
  freeSpinsPerTrigger: number;
  minBetPerLine: number;
  maxBetPerLine: number;
}

// ---------------------------------------------------------------- poker (chips are minor units)

export interface PokerSeat {
  seatNo: number;
  userId?: string;
  username?: string;
  stack?: number;
  currentBet?: number;
  status?: 'ACTIVE' | 'FOLDED' | 'ALL_IN' | 'SITTING_OUT';
  inHand?: boolean;
  sittingOut?: boolean;
  connected?: boolean;
  cards?: string[];
}

export interface HandResult {
  handNumber: number;
  board: string[];
  rake: number;
  winnings: Record<string, number>;
  contributions: Record<string, number>;
  shown: Record<string, { cards: string[]; handRank: string }>;
  showdown: boolean;
}

export interface PokerPublicState {
  tableId: string;
  name: string;
  smallBlind: number;
  bigBlind: number;
  maxSeats: number;
  handNumber: number;
  handInProgress: boolean;
  round: 'PRE_FLOP' | 'FLOP' | 'TURN' | 'RIVER' | 'SHOWDOWN' | null;
  board: string[];
  pot: number;
  currentHighBet: number;
  dealerSeat: number;
  turnSeat: number;
  turnDeadline: string | null;
  seats: PokerSeat[];
  lastResult?: HandResult;
}

export interface LegalActions {
  canCheck: boolean;
  toCall: number;
  canRaise: boolean;
  raiseType: 'BET' | 'RAISE';
  minRaiseTo: number;
  maxRaiseTo: number;
}

export interface PokerPrivateState {
  tableId: string;
  seated: boolean;
  seatNo?: number;
  holeCards?: string[];
  sittingOut?: boolean;
  legalActions?: LegalActions;
}

/** One Deposited event from the Sepolia cashier contract, as the core sees it. */
export interface EthDeposit {
  id: string;
  txHash: string;
  fromAddress: string;
  amountEth: string;
  amountTokens: number | null;
  status: 'credited' | 'unlinked' | 'held';
  holdReason: string | null;
  blockNumber: number;
  createdAt: string;
}

/** GET /api/wallet/eth: MetaMask + Sepolia settings and this player's link and deposits. */
export interface EthStatus {
  enabled: boolean;
  chainId: number;
  contractAddress: string | null;
  tokensPerEth: number;
  confirmations: number;
  linkedAddress: string | null;
  deposits: EthDeposit[];
}
